-- Every change to a row of a sheet, for showing the sheet as of a past date (see history/AsOfView): each
-- insert, update or delete of a row of a sheet's tables, kept in the order made (id) with the sheet's
-- today when it was made (on_date) and the row's values before and after (each a serialized Object[] in
-- the table's column order; old_row null for an insert, new_row null for a delete). The rows are
-- captured by a trigger on each table (history/RowCapture), installed at start-up.
CREATE TABLE row_change (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200) NOT NULL,
    on_date    DATE         NOT NULL,
    table_name VARCHAR(100) NOT NULL,
    old_row    VARBINARY(1000000),
    new_row    VARBINARY(1000000)
);
CREATE INDEX row_change_sheet ON row_change (sheet_id, id);

-- The tables a sheet's view is replayed into: one per captured table, created at start-up.
CREATE SCHEMA IF NOT EXISTS asof;
package net.officefloor.hq.app.history;

import java.sql.Date;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Supplier;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.server.http.HttpHeader;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** A signed-in user's screen showing a sheet as of a date (the X-As-Of header, yyyy-mm-dd): the sheet as it stood
 *  at the end of that day. Every change kept in row_change (see {@link RowCapture}) made while the sheet's today
 *  was on or before the date counts, in the order made, every later one does not (the sheet itself always
 *  exists); the date stands in for the sheet's today. A read replays those changes into the asof schema's tables,
 *  runs the usual read against them, and removes them again, all in one transaction, so no other read sees them.
 *  The sheets it falls back to (its parent as it stood then, that one's parent and so on, and
 *  the sheets it was cloned from) are not shown as of the
 *  date: their rows are read as they are now, so a rate it inherits applies as it does live.
 *  While the date is set, every change is refused.
 *
 *  A screen may instead preview the sheet at a date (the X-Preview header, yyyy-mm-dd): its rows as they are now,
 *  copied into the asof schema the same way, with the date standing in for its today, so every figure that
 *  depends on today is worked out as of that date. Only reads look at it: every change still uses the sheet's
 *  real today, and nothing a change of today does happens. */
@Component
public class AsOfView {

    public static final String HEADER = "X-As-Of";
    public static final String PREVIEW_HEADER = "X-Preview";

    private final JdbcTemplate jdbc;
    private final RowCaptureInstaller installer;
    private final TransactionTemplate transaction;

    public AsOfView(JdbcTemplate jdbc, RowCaptureInstaller installer, PlatformTransactionManager transactions) {
        this.jdbc = jdbc;
        this.installer = installer;
        this.transaction = new TransactionTemplate(transactions);
    }

    /** The as-of date the request's screen shows; null when it shows the sheet as it is now. */
    public static LocalDate of(ServerHttpConnection connection) throws BadRequestException {
        return date(connection, HEADER, "as-of");
    }

    /** The date the request's screen previews the sheet at; null when it shows the sheet at its real today. */
    public static LocalDate previewOf(ServerHttpConnection connection) throws BadRequestException {
        return date(connection, PREVIEW_HEADER, "preview");
    }

    private static LocalDate date(ServerHttpConnection connection, String name, String what) throws BadRequestException {
        String raw = "";
        for (HttpHeader header : connection.getRequest().getHeaders()) {
            if (name.equalsIgnoreCase(header.getName())) {
                raw = header.getValue() == null ? "" : header.getValue().trim();
                break;
            }
        }
        if (raw.isEmpty()) return null;
        try {
            return LocalDate.parse(raw);
        } catch (DateTimeParseException e) {
            throw new BadRequestException(what + " date must be yyyy-mm-dd");
        }
    }

    /** Refuse any change made from a screen showing the sheet as of a date (400, nothing written). */
    public static void refuse(ServerHttpConnection connection) throws BadRequestException {
        if (of(connection) != null) {
            throw new BadRequestException("the sheet is shown as of a date: nothing can be changed");
        }
    }

    /** The read, as the request's screen shows the sheet: as of its date when one is set, else previewed at its
     *  preview date when one is set, else as it is now. */
    public <T> T read(ServerHttpConnection connection, String sheetId, Supplier<T> read) throws BadRequestException {
        LocalDate day = of(connection);
        if (day != null) return readAt(sheetId, day, read);
        LocalDate preview = previewOf(connection);
        if (preview != null) return readPreview(sheetId, preview, read);
        return read.get();
    }

    /** The read run against the sheet as it stood at the end of a day, the day standing in for its today. */
    public <T> T readAt(String sheetId, LocalDate day, Supplier<T> read) {
        return readIn(sheetId, day, true, read);
    }

    /** The read run against the sheet as it is now, a day standing in for its today. */
    public <T> T readPreview(String sheetId, LocalDate day, Supplier<T> read) {
        return readIn(sheetId, day, false, read);
    }

    private <T> T readIn(String sheetId, LocalDate day, boolean asOf, Supplier<T> read) {
        return transaction.execute(status -> {
            Map<String, List<Object[]>> rows = asOf ? replay(sheetId, day) : new LinkedHashMap<>();
            if (!asOf) copy(sheetId);
            for (Map.Entry<String, List<Object[]>> e : rows.entrySet()) {
                RowCaptureInstaller.Table table = installer.tables().get(e.getKey());
                String marks = String.join(", ", table.columns().stream().map(c -> "?").toList());
                for (Object[] row : e.getValue()) {
                    jdbc.update("INSERT INTO ASOF.\"" + table.name() + "\" VALUES (" + marks + ")", row);
                }
            }
            if (asOf && rows.getOrDefault("SHEET", List.of()).isEmpty()) {
                jdbc.update("INSERT INTO ASOF.SHEET SELECT * FROM PUBLIC.SHEET WHERE id = ?", sheetId);
            }
            jdbc.update("UPDATE ASOF.SHEET SET today = ? WHERE id = ?", Date.valueOf(day), sheetId);
            List<String> shown = new ArrayList<>(List.of(sheetId));
            for (String at = parent("ASOF", sheetId); at != null && !shown.contains(at); at = parent("PUBLIC", at)) {
                shown.add(at);
                copy(at);
            }
            for (String at : fallbacks(sheetId)) {
                if (shown.contains(at)) continue;
                shown.add(at);
                copy(at);
            }
            jdbc.execute("SET SCHEMA ASOF");
            try {
                return read.get();
            } finally {
                jdbc.execute("SET SCHEMA PUBLIC");
                for (String at : shown) {
                    for (RowCaptureInstaller.Table table : installer.tables().values()) {
                        jdbc.update("DELETE FROM ASOF.\"" + table.name() + "\" WHERE \""
                                + table.columns().get(table.sheetColumn()) + "\" = ?", at);
                    }
                }
            }
        });
    }

    /** Copy a sheet's rows as they are now into the asof schema. */
    private void copy(String sheetId) {
        for (RowCaptureInstaller.Table table : installer.tables().values()) {
            jdbc.update("INSERT INTO ASOF.\"" + table.name() + "\" SELECT * FROM PUBLIC.\"" + table.name()
                    + "\" WHERE \"" + table.columns().get(table.sheetColumn()) + "\" = ?", sheetId);
        }
    }

    /** Every sheet a sheet may fall back to: its parent and the sheet it was cloned from as they stood then, then
     *  theirs as they are now, and so on. */
    private List<String> fallbacks(String sheetId) {
        List<String> found = new ArrayList<>();
        java.util.Deque<String> pending = new java.util.ArrayDeque<>(List.of(sheetId));
        while (!pending.isEmpty()) {
            String at = pending.poll();
            String schema = at.equals(sheetId) ? "ASOF" : "PUBLIC";
            for (Map<String, Object> row : jdbc.queryForList("SELECT parent_id, cloned_from FROM " + schema + ".SHEET WHERE id = ?",
                    at)) {
                for (Object next : row.values()) {
                    if (next != null && !next.equals(sheetId) && !found.contains(next)) {
                        found.add((String) next);
                        pending.add((String) next);
                    }
                }
            }
        }
        return found;
    }

    /** A sheet's parent in a schema; null when it has none (or is not there). */
    private String parent(String schema, String sheetId) {
        List<String> found = jdbc.queryForList("SELECT parent_id FROM " + schema + ".SHEET WHERE id = ?", String.class, sheetId);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The sheet's rows as of the end of a day, by table: the kept changes made while its today was on or before
     *  it, applied in the order made. An insert adds its row (the sheet's own always counts); an update changes
     *  the columns it changed of the row it changed (found by its primary key, else by all its values), and a
     *  delete removes that row; one whose row is not there (it was added later) changes nothing. */
    private Map<String, List<Object[]>> replay(String sheetId, LocalDate day) {
        Map<String, List<Object[]>> rows = new LinkedHashMap<>();
        Date on = Date.valueOf(day);
        jdbc.query("SELECT on_date, table_name, old_row, new_row FROM ROW_CHANGE WHERE sheet_id = ? ORDER BY id", rs -> {
            RowCaptureInstaller.Table table = installer.tables().get(rs.getString("table_name"));
            if (table == null) return;
            Object[] before = RowCapture.read(rs.getBytes("old_row"));
            Object[] after = RowCapture.read(rs.getBytes("new_row"));
            boolean counts = !rs.getDate("on_date").after(on) || (before == null && table.name().equals("SHEET"));
            if (!counts) return;
            List<Object[]> kept = rows.computeIfAbsent(table.name(), k -> new ArrayList<>());
            if (before == null) {
                if (!table.key().isEmpty()) {
                    int same = find(kept, table, after);
                    if (same >= 0) kept.remove(same);
                }
                kept.add(after.clone());
                return;
            }
            int found = find(kept, table, before);
            if (found < 0) return;
            if (after == null) {
                kept.remove(found);
                return;
            }
            Object[] row = kept.get(found);
            for (int i = 0; i < row.length && i < after.length; i++) {
                if (!Objects.deepEquals(before[i], after[i])) row[i] = after[i];
            }
        }, sheetId);
        return rows;
    }

    /** The position of the kept row a change's row is: the one with its primary key, else with all its values. */
    private static int find(List<Object[]> kept, RowCaptureInstaller.Table table, Object[] row) {
        for (int i = kept.size() - 1; i >= 0; i--) {
            Object[] k = kept.get(i);
            boolean same = true;
            if (table.key().isEmpty()) {
                same = Arrays.deepEquals(k, row);
            } else {
                for (int c : table.key()) same &= Objects.deepEquals(k[c], row[c]);
            }
            if (same) return i;
        }
        return -1;
    }
}
package net.officefloor.hq.app.settings;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.history.AsOfView;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadSettings {
    public void load(@PathVariable("sheetId") String sheetId, ServerHttpConnection connection,
            SettingsRepository repository, AsOfView view, Out<Settings> settings) throws BadRequestException {
        CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        settings.set(view.read(connection, id, () -> repository.load(id)));
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.history.AsOfView;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadRates {
    public void load(@PathVariable("sheetId") String sheetId, ServerHttpConnection connection,
            RateRepository repository, SettingsRepository settings, AsOfView view, Out<Rates> rates)
            throws BadRequestException {
        CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        rates.set(view.read(connection, id, () -> new Rates(repository.list(id),
                settings.rateAncestors(id).stream().map(repository::list).toList(), repository.earlier(id),
                settings.rateAncestors(id).stream().map(repository::earlier).toList())));
    }
}
package net.officefloor.hq.app.history;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.Function;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.person.Hold;
import net.officefloor.hq.app.settings.SettingsRepository;

/** A sheet as it stood at the end of a day: what the changes made while the sheet's today was on or
 *  before that day left (see {@link HistoryRepository#asOf}). The day stands in for the sheet's today in
 *  every figure, worked out by the same rules as the live ones in ClaimRepository: the grade and rate in
 *  force, the rounding, the floor, late charges, holds and retirements.
 *
 *  @param claims        each claim's values then, by claim id (a claim added later is absent)
 *  @param grades        each person's grades then, by person id, each by from-date (null: from the beginning of time)
 *  @param rates         each grade's rates then, by grade, each by from-date the rates set from it, in the order set
 *  @param settings      each dated setting's values then, by key, each by from-date
 *  @param policyDate    the policy date then (null: blank, the day itself)
 *  @param holds         each person's holds then, by person id
 *  @param retiredFrom   the date each person was retired from then, by person id (absent: not retired)
 *  @param correctedDate the date of a person's claim with a number (person id, number), for a correction's rounding
 *  @param added         each claim's added number, by claim id (see V83__forward_only_rate.sql)
 */
public record SheetAsOf(LocalDate day, Map<Long, Claim> claims, Map<Long, TreeMap<LocalDate, String>> grades,
        Map<String, TreeMap<LocalDate, List<Rate>>> rates, Map<String, TreeMap<LocalDate, String>> settings,
        LocalDate policyDate, Map<Long, List<Hold>> holds, Map<Long, String> retiredFrom,
        Function<Claim, String> correctedDate, Map<Long, Long> added) {

    /** A rate then: its percent and to-date (null: with no end), and, when forward-only, the claim-added number it
     *  was set at (it applies only to claims with a higher one; null: to every claim). */
    public record Rate(BigDecimal pct, LocalDate to, Long after) {
    }

    /** The minimum date, standing for "from the beginning of time" (a null from-date). */
    public static final LocalDate BEGINNING = LocalDate.of(1, 1, 1);

    /** A person's claims then, newest first. */
    public List<Claim> claimsOf(long personId) {
        List<Claim> mine = new ArrayList<>();
        for (Claim c : claims.values()) {
            if (c.personId() == personId) mine.add(c);
        }
        mine.sort((a, b) -> Long.compare(b.id(), a.id()));
        return mine;
    }

    /** The holds that acted on a person's live totals then: none of their own holds (a hold acts only on pool cuts),
     *  only, once their retirement date was reached, a hold over every date. */
    public List<Hold> liveHolds(long personId) {
        List<Hold> all = new ArrayList<>();
        String retired = retiredFrom.get(personId);
        if (retired != null && retired.compareTo(day.toString()) <= 0) all.add(new Hold(null, null));
        return all;
    }

    private static <V> V latest(TreeMap<LocalDate, V> dated, LocalDate on) {
        if (dated == null) return null;
        Map.Entry<LocalDate, V> e = dated.floorEntry(on);
        return e == null ? null : e.getValue();
    }

    /** The grade a person had then on a date. */
    public String gradeOn(long personId, LocalDate on) {
        return latest(grades.get(personId), on);
    }

    /** The rate in force then for a person on a date, whatever claim it is for; null when there is none. */
    private Rate rateOn(long personId, LocalDate on) {
        return rateOn(personId, on, null);
    }

    /** The rate that would apply then to a person on a date for a claim with an added number (null: any claim): of
     *  the latest from-date on or before it with a rate set that applies to the claim, the last such set; null when
     *  there is none. */
    private Rate rateOn(long personId, LocalDate on, Long claimAdded) {
        String grade = gradeOn(personId, on);
        TreeMap<LocalDate, List<Rate>> dated = grade == null ? null : rates.get(grade);
        if (dated == null) return null;
        for (Map.Entry<LocalDate, List<Rate>> e = dated.floorEntry(on); e != null; e = dated.lowerEntry(e.getKey())) {
            List<Rate> sets = e.getValue();
            for (int i = sets.size() - 1; i >= 0; i--) {
                Rate r = sets.get(i);
                if (claimAdded == null || r.after() == null || r.after() < claimAdded) return r;
            }
        }
        return null;
    }

    /** A claim's added number; the highest there is when unknown. */
    private Long addedOf(Claim claim) {
        Long n = added.get(claim.id());
        return n == null ? Long.MAX_VALUE : n;
    }

    /** A dated setting's value then on a date: a list holding the value (null when blank), empty when none was recorded. */
    private List<String> setting(String key, LocalDate on) {
        TreeMap<LocalDate, String> dated = settings.get(key);
        if (dated == null) return List.of();
        Map.Entry<LocalDate, String> e = dated.floorEntry(on);
        if (e == null) return List.of();
        List<String> found = new ArrayList<>();
        found.add(e.getValue());
        return found;
    }

    /** The floor then on a date; 1.00 before any was recorded. */
    public BigDecimal floor(LocalDate on) {
        List<String> found = setting("floor", on);
        return found.isEmpty() || found.get(0) == null ? BigDecimal.ONE.setScale(2) : new BigDecimal(found.get(0)).setScale(2);
    }

    /** The late percent then on a date; 0.00 before any was recorded. */
    public BigDecimal latePct(LocalDate on) {
        List<String> found = setting("late-pct", on);
        return found.isEmpty() || found.get(0) == null ? BigDecimal.ZERO.setScale(2) : new BigDecimal(found.get(0)).setScale(2);
    }

    /** The cap in force on the day; null when there was none. */
    public BigDecimal cap() {
        List<String> found = setting("cap", day);
        return found.isEmpty() || found.get(0) == null ? null : new BigDecimal(found.get(0));
    }

    /** A claim's rate figure then, not floored; null when no rate applied. */
    public BigDecimal due(Claim claim) {
        LocalDate date = LocalDate.parse(claim.date());
        Rate rate = rateOn(claim.personId(), date, addedOf(claim));
        if (rate == null || (rate.to() != null && rate.to().isBefore(date))) return null;
        return new BigDecimal(claim.amount()).multiply(rate.pct()).movePointLeft(2).setScale(2, rounding(claim));
    }

    /** How a claim's figures rounded then: by the rounding mode in force on its date when there was one; else
     *  half up when dated before the policy date (blank: the day), else half to even; a correction by the date
     *  of the claim it corrects. */
    private RoundingMode rounding(Claim claim) {
        String date = claim.date();
        if (claim.corrects() != null) {
            String corrected = correctedDate.apply(claim);
            if (corrected != null) date = corrected;
        }
        List<String> mode = setting("rounding", LocalDate.parse(date));
        RoundingMode set = mode.isEmpty() ? null : SettingsRepository.roundingMode(mode.get(0));
        if (set != null) return set;
        LocalDate policy = policyDate != null ? policyDate : day;
        return LocalDate.parse(date).isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** A claim's figure then: its settled due, else the one a statement bound it to (none when bound to
     *  n/a), else its rate figure; null when it had none. */
    public BigDecimal figure(Claim claim) {
        if (claim.due() != null) return new BigDecimal(claim.due());
        if (claim.bound() && claim.statedNa()) return null;
        if (claim.bound() && claim.statedDue() != null) return new BigDecimal(claim.statedDue());
        return due(claim);
    }

    /** A claim's due then: its settled due, else the due a statement bound it to (as shown then), else its figure raised to at least the floor plus its late
     *  charges on the day on that floored figure (a correction has neither); null when it had no figure. */
    public BigDecimal dueNow(Claim claim) {
        if (claim.due() != null) return new BigDecimal(claim.due());
        if (claim.bound() && (claim.statedNa() || claim.statedDue() != null)) return figure(claim);
        BigDecimal figure = figure(claim);
        if (figure == null || new BigDecimal(claim.amount()).signum() < 0) return figure;
        BigDecimal floored = figure.max(floor(LocalDate.parse(claim.date())));
        return floored.add(lateCharge(claim, floored));
    }

    /** The day a claim's overdue days counted from then: its due-by plus the grace days, then in force on its date,
     *  of the grade its person had on that date (its due-by when none). */
    public LocalDate overdueFrom(Claim claim) {
        LocalDate dueBy = LocalDate.parse(claim.dueBy());
        LocalDate date = LocalDate.parse(claim.date());
        String grade = gradeOn(claim.personId(), date);
        if (grade == null) return dueBy;
        List<String> found = setting("grace-" + grade, date);
        return found.isEmpty() || found.get(0) == null ? dueBy : dueBy.plusDays(Integer.parseInt(found.get(0)));
    }

    private BigDecimal lateCharge(Claim claim, BigDecimal figure) {
        BigDecimal charge = BigDecimal.ZERO.setScale(2);
        if (!claim.open() || claim.deferred() || claim.waived()) return charge;
        LocalDate dueBy = overdueFrom(claim);
        long periods = dueBy.isBefore(day) ? ChronoUnit.DAYS.between(dueBy, day) / 30 : 0;
        RoundingMode rounding = rounding(claim);
        for (long n = 1; n <= periods; n++) {
            BigDecimal pct = latePct(dueBy.plusDays(30 * n));
            if (pct.signum() == 0) continue;
            charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding));
        }
        return charge;
    }

    /** Whether the rate that would apply to a claim then had ended before its date. */
    public boolean rateEnded(Claim claim) {
        LocalDate date = LocalDate.parse(claim.date());
        Rate rate = rateOn(claim.personId(), date, addedOf(claim));
        return rate != null && rate.to() != null && rate.to().isBefore(date);
    }

    /** Whether a rate for the grade a person had on the day was in force on it. */
    public boolean rated(long personId) {
        Rate rate = rateOn(personId, day);
        return rate != null && (rate.to() == null || !rate.to().isBefore(day));
    }
}
